import { ComponentProps } from "react";
import { ClassNameValue, twJoin } from "tailwind-merge";
import { Link } from "wasp/client/router";

type ButtonSize = "md" | "sm" | "xs";
type ButtonVariant = "primary" | "danger" | "ghost";

interface ButtonProps extends ComponentProps<"button"> {
  size?: ButtonSize;
  variant?: ButtonVariant;
}

export function Button({
  children,
  className,
  type = "button",
  size = "md",
  variant = "primary",
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      className={getButtonClasses({
        size,
        variant,
        className,
      })}
      {...props}
    >
      {children}
    </button>
  );
}

type ButtonLinkProps = ComponentProps<typeof Link> & {
  size?: ButtonSize;
  variant?: ButtonVariant;
};

export function ButtonLink({
  children,
  className,
  size = "md",
  variant = "primary",
  ...props
}: ButtonLinkProps) {
  return (
    <Link
      className={getButtonClasses({
        size,
        variant,
        className,
      })}
      {...props}
    >
      {children}
    </Link>
  );
}

function getButtonClasses({
  size,
  variant,
  className,
}: {
  size: ButtonSize;
  variant: ButtonVariant;
  className: ClassNameValue;
}): string {
  return twJoin(
    "rounded-md font-semibold",
    variantStyles[variant],
    sizeStyles[size],
    className,
  );
}

const sizeStyles: Record<ButtonSize, ClassNameValue> = {
  md: "px-4 py-2",
  sm: "px-3 py-1.5 text-sm",
  xs: "px-2 py-1 text-xs",
};

const variantStyles: Record<ButtonVariant, ClassNameValue> = {
  primary:
    "bg-primary-500 hover:bg-primary-400 active:bg-primary-300 text-neutral-800",
  danger: "bg-red-600 text-white hover:bg-red-700 active:bg-red-800",
  ghost:
    "bg-transparent text-neutral-800 hover:bg-neutral-100 active:bg-neutral-200",
};

import { ComponentProps, useId } from "react";
import { ControllerFieldState } from "react-hook-form";
import { twJoin } from "tailwind-merge";

interface InputProps extends Omit<ComponentProps<"input">, "children" | "id"> {
  label: string;
  fieldState: ControllerFieldState;
}

export function Input({ className, label, fieldState, ...props }: InputProps) {
  const id = useId();

  return (
    <div className="flex flex-col gap-1">
      <label htmlFor={id} className="label">
        {label}
      </label>

      <input
        id={id}
        className={twJoin(
          "w-full rounded-md border border-neutral-300 bg-white px-3 py-2 text-neutral-800 shadow-xs focus:border-primary-500 focus:outline-hidden focus:ring-1 focus:ring-primary-500",
          className,
        )}
        {...props}
      />

      {fieldState.error && (
        <span className="text-sm text-red-500">{fieldState.error.message}</span>
      )}
    </div>
  );
}

import { type Spec, action, query } from "@wasp.sh/spec";
import { createTag } from "./actions" with { type: "ref" };
import { getTags } from "./queries" with { type: "ref" };

export const tagsSpec: Spec = [
  query(getTags, { entities: ["Tag"] }),
  action(createTag, { entities: ["Tag"] }),
];

import { useCallback } from "react";
import { Controller, SubmitHandler, useForm } from "react-hook-form";
import { createTask, getTags, useQuery } from "wasp/client/operations";
import { Tag } from "wasp/entities";
import { Button } from "../../shared/components/Button";
import { Input } from "../../shared/components/Input";
import { CreateTagDialog } from "../../tags/components/CreateTagDialog";
import { TagLabel } from "../../tags/components/TagLabel";

interface CreateTaskFormValues {
  description: string;
  tagIds: string[];
}

export function CreateTaskForm() {
  const { data: tags } = useQuery(getTags);
  const { handleSubmit, getValues, setValue, watch, control, reset } =
    useForm<CreateTaskFormValues>({
      defaultValues: {
        description: "",
        tagIds: [],
      },
    });

  const onSubmit: SubmitHandler<CreateTaskFormValues> = async (data, event) => {
    event?.stopPropagation();

    try {
      await createTask(data);
    } catch (err: unknown) {
      window.alert(`Error while creating task: ${String(err)}`);
    } finally {
      reset();
    }
  };

  const toggleTag = useCallback(
    function toggleTag(id: Tag["id"]) {
      const tagIds = getValues("tagIds");
      if (tagIds.includes(id)) {
        setValue(
          "tagIds",
          tagIds.filter((tagId) => tagId !== id),
        );
      } else {
        setValue("tagIds", [...tagIds, id]);
      }
    },
    [getValues, setValue],
  );

  const tagIds = watch("tagIds");

  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="flex w-full flex-col gap-6"
      id="create-task"
    >
      <h2 className="text-xl font-semibold">Create a new task</h2>
      <Controller
        name="description"
        control={control}
        rules={{
          required: { value: true, message: "Description is required" },
        }}
        render={({ field, fieldState }) => (
          <Input
            label="Description"
            placeholder="What do I need to do?"
            fieldState={fieldState}
            {...field}
          />
        )}
      />

      <div className="flex flex-col gap-2">
        <span className="label">Select tags</span>
        <div className="flex flex-wrap gap-4">
          {tags && tags.length > 0 && (
            <ul className="flex flex-wrap gap-2">
              {tags.map((tag) => (
                <li key={tag.id}>
                  <button type="button" onClick={() => toggleTag(tag.id)}>
                    <TagLabel
                      tag={tag}
                      isActive={tagIds.includes(tag.id)}
                      showColorCircle
                    />
                  </button>
                </li>
              ))}
            </ul>
          )}
          <CreateTagDialog />
        </div>
      </div>
      <Button type="submit" className="self-end">
        Create
      </Button>
    </form>
  );
}

