import { type Spec, action, page, query, route } from "@wasp.sh/spec";
import {
  createChannel,
  createMessage,
  markAsRead,
} from "./actions" with { type: "ref" };
import {
  getChannel,
  getChannelMessages,
  getChannels,
} from "./queries" with { type: "ref" };
import { ChannelPage } from "./ChannelPage" with { type: "ref" };
import { MainPage } from "./MainPage" with { type: "ref" };

export const chatSpec: Spec = [
  route("MainRoute", "/", page(MainPage, { authRequired: true })),
  route(
    "ChannelRoute",
    "/channel/:id",
    page(ChannelPage, { authRequired: true }),
  ),

  query(getChannels, { entities: ["Channel"] }),
  query(getChannel, { entities: ["Channel"] }),
  query(getChannelMessages, {
    entities: ["Message", "ReadReceipt", "User"],
  }),

  action(createChannel, { entities: ["Channel"] }),
  action(createMessage, { entities: ["Message", "ReadReceipt"] }),
  action(markAsRead, { entities: ["ReadReceipt", "Message"] }),
];

import { HttpError } from "wasp/server";
import {
  type GetChannel,
  type GetChannelMessages,
  type GetChannels,
} from "wasp/server/operations";
import { type Channel } from "wasp/entities";

export const getChannels: GetChannels<void, Channel[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Channel.findMany({
    orderBy: { name: "asc" },
  });
};

type GetChannelArgs = { channelId: number };

export const getChannel: GetChannel<GetChannelArgs, Channel | null> = async (
  { channelId },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Channel.findUnique({
    where: { id: channelId },
  });
};

export interface MessageReader {
  userId: number;
  username: string;
}

export interface ChannelMessage {
  id: number;
  content: string;
  createdAt: Date;
  channelId: number;
  senderId: number;
  sender: {
    id: number;
    username: string;
  };
  readers: MessageReader[];
}

type GetChannelMessagesArgs = { channelId: number };

export const getChannelMessages: GetChannelMessages<
  GetChannelMessagesArgs,
  ChannelMessage[]
> = async ({ channelId }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const [messages, readReceipts] = await Promise.all([
    context.entities.Message.findMany({
      where: { channelId },
      orderBy: { createdAt: "asc" },
      include: {
        sender: {
          select: { id: true, username: true },
        },
      },
    }),
    context.entities.ReadReceipt.findMany({
      where: { channelId },
      include: {
        user: {
          select: { id: true, username: true },
        },
      },
    }),
  ]);

  return messages.map((message) => {
    const readers: MessageReader[] = readReceipts
      .filter(
        (receipt) =>
          receipt.userId !== message.senderId &&
          receipt.lastReadMessageId >= message.id,
      )
      .map((receipt) => ({
        userId: receipt.user.id,
        username: receipt.user.username,
      }));

    return {
      id: message.id,
      content: message.content,
      createdAt: message.createdAt,
      channelId: message.channelId,
      senderId: message.senderId,
      sender: message.sender,
      readers,
    };
  });
};

import {
  type Server,
  type WaspSocketData,
  type WebSocketDefinition,
} from "wasp/server/webSocket";

// -----------------------------------------------------------------------------
// Critical seam: server-side Actions (e.g. createMessage, markAsRead) need to be
// able to emit WebSocket events. Since Actions don't get the `io` instance passed
// to them directly, we stash a module-level reference to it here (set once when
// `webSocketFn` runs on server start) and expose a getter that other server
// modules can import and use.
// -----------------------------------------------------------------------------
let ioInstance: Server<ServerToClientEvents, ClientToServerEvents> | null =
  null;

export function getIo(): Server<ServerToClientEvents, ClientToServerEvents> | null {
  return ioInstance;
}

// channelId -> (socketId -> username) of sockets currently "in" that channel.
const channelSockets = new Map<number, Map<string, string>>();
// socketId -> set of channelIds that socket has joined (used for disconnect cleanup).
const socketChannels = new Map<string, Set<number>>();

function addActiveUser(channelId: number, socketId: string, username: string) {
  if (!channelSockets.has(channelId)) {
    channelSockets.set(channelId, new Map());
  }
  channelSockets.get(channelId)!.set(socketId, username);

  if (!socketChannels.has(socketId)) {
    socketChannels.set(socketId, new Set());
  }
  socketChannels.get(socketId)!.add(channelId);
}

function removeActiveUser(channelId: number, socketId: string) {
  channelSockets.get(channelId)?.delete(socketId);
  socketChannels.get(socketId)?.delete(channelId);
}

function getActiveUsernames(channelId: number): string[] {
  const sockets = channelSockets.get(channelId);
  if (!sockets) {
    return [];
  }
  return Array.from(new Set(sockets.values()));
}

function broadcastActiveUsers(
  io: Server<ServerToClientEvents, ClientToServerEvents>,
  channelId: number,
) {
  io.to(getChannelRoom(channelId)).emit(
    "activeUsers",
    getActiveUsernames(channelId),
  );
}

function getChannelRoom(channelId: number): string {
  return `channel-${channelId}`;
}

export const webSocketFn: WebSocketFn = (io, _context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    const username = socket.data.user?.username;

    socket.on("joinChannel", ({ channelId }) => {
      socket.join(getChannelRoom(channelId));
      if (username) {
        addActiveUser(channelId, socket.id, username);
        broadcastActiveUsers(io, channelId);
      }
    });

    socket.on("leaveChannel", ({ channelId }) => {
      socket.leave(getChannelRoom(channelId));
      removeActiveUser(channelId, socket.id);
      broadcastActiveUsers(io, channelId);
    });

    socket.on("typing", ({ channelId, isTyping }) => {
      if (!username) {
        return;
      }
      socket.to(getChannelRoom(channelId)).emit("typing", {
        username,
        isTyping,
      });
    });

    socket.on("disconnect", () => {
      const channelIds = socketChannels.get(socket.id);
      if (channelIds) {
        for (const channelId of Array.from(channelIds)) {
          removeActiveUser(channelId, socket.id);
          broadcastActiveUsers(io, channelId);
        }
        socketChannels.delete(socket.id);
      }
    });
  });
};

// Typing our WebSocket function with the events and payloads gives us
// full-stack type safety on the client as well.
type WebSocketFn = WebSocketDefinition<
  ClientToServerEvents,
  ServerToClientEvents,
  InterServerEvents,
  SocketData
>;

export interface ChatMessagePayload {
  id: number;
  content: string;
  createdAt: Date;
  channelId: number;
  senderId: number;
  sender: {
    id: number;
    username: string;
  };
}

export interface ReadReceiptUpdatedPayload {
  userId: number;
  username: string;
  lastReadMessageId: number;
}

interface ServerToClientEvents {
  activeUsers: (usernames: string[]) => void;
  typing: (data: { username: string; isTyping: boolean }) => void;
  messageCreated: (message: ChatMessagePayload) => void;
  readReceiptUpdated: (data: ReadReceiptUpdatedPayload) => void;
}

interface ClientToServerEvents {
  joinChannel: (data: { channelId: number }) => void;
  leaveChannel: (data: { channelId: number }) => void;
  typing: (data: { channelId: number; isTyping: boolean }) => void;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
interface InterServerEvents {}

interface SocketData extends WaspSocketData {}

import { HttpError } from "wasp/server";
import {
  type CreateChannel,
  type CreateMessage,
  type MarkAsRead,
} from "wasp/server/operations";
import { type Channel, type Message, type ReadReceipt } from "wasp/entities";
import { getIo, type ChatMessagePayload } from "../webSocket";

type CreateChannelArgs = { name: string };

export const createChannel: CreateChannel<CreateChannelArgs, Channel> = async (
  { name },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const existing = await context.entities.Channel.findUnique({
    where: { name },
  });
  if (existing) {
    throw new HttpError(400, `Channel "${name}" already exists.`);
  }

  return context.entities.Channel.create({
    data: { name },
  });
};

type CreateMessageArgs = { channelId: number; content: string };

export const createMessage: CreateMessage<
  CreateMessageArgs,
  Message
> = async ({ channelId, content }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const message = await context.entities.Message.create({
    data: {
      content,
      sender: { connect: { id: context.user.id } },
      channel: { connect: { id: channelId } },
    },
    include: {
      sender: {
        select: { id: true, username: true },
      },
    },
  });

  await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    create: {
      user: { connect: { id: context.user.id } },
      channel: { connect: { id: channelId } },
      lastReadMessage: { connect: { id: message.id } },
    },
    update: {
      lastReadMessage: { connect: { id: message.id } },
    },
  });

  const payload: ChatMessagePayload = {
    id: message.id,
    content: message.content,
    createdAt: message.createdAt,
    channelId: message.channelId,
    senderId: message.senderId,
    sender: message.sender,
  };

  getIo()?.to(`channel-${channelId}`).emit("messageCreated", payload);

  return message;
};

type MarkAsReadArgs = { channelId: number; lastReadMessageId: number };

export const markAsRead: MarkAsRead<MarkAsReadArgs, ReadReceipt> = async (
  { channelId, lastReadMessageId },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const readReceipt = await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    create: {
      user: { connect: { id: context.user.id } },
      channel: { connect: { id: channelId } },
      lastReadMessage: { connect: { id: lastReadMessageId } },
    },
    update: {
      lastReadMessage: { connect: { id: lastReadMessageId } },
    },
  });

  getIo()
    ?.to(`channel-${channelId}`)
    .emit("readReceiptUpdated", {
      userId: context.user.id,
      username: context.user.username,
      lastReadMessageId,
    });

  return readReceipt;
};

import type { DbSeedFn, PrismaClient } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

export const seedDevData: DbSeedFn = async (prisma) => {
  await createUser(prisma, { username: "alice", password: "password123" });
  await createUser(prisma, { username: "bob", password: "password123" });

  await prisma.channel.upsert({
    where: { name: "#general" },
    create: { name: "#general" },
    update: {},
  });
  await prisma.channel.upsert({
    where: { name: "#random" },
    create: { name: "#random" },
    update: {},
  });
};

async function createUser(
  prisma: PrismaClient,
  data: { username: string; password: string },
) {
  const existing = await prisma.user.findUnique({
    where: { username: data.username },
  });
  if (existing) {
    return existing;
  }

  return prisma.user.create({
    data: {
      username: data.username,
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: data.username,
              providerData: await sanitizeAndSerializeProviderData<"username">(
                {
                  hashedPassword: data.password,
                },
              ),
            },
          },
        },
      },
    },
  });
}

import { Link } from "react-router";
