import { useState } from "react";
import { Link } from "react-router";
import type { AuthUser } from "wasp/auth";
import { logout } from "wasp/client/auth";
import { createChannel, getChannels, useQuery } from "wasp/client/operations";

export function MainPage({ user }: { user: AuthUser }) {
  const { data: channels } = useQuery(getChannels);
  const [channelName, setChannelName] = useState("");
  const [error, setError] = useState<string | null>(null);

  async function handleCreateChannel(e: React.FormEvent) {
    e.preventDefault();
    const name = channelName.trim();
    if (!name) {
      return;
    }
    setError(null);
    try {
      await createChannel({ name });
      setChannelName("");
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    }
  }

  return (
    <div className="mx-auto flex max-w-2xl flex-col gap-8 p-8">
      <div className="flex items-center justify-between">
        <h1 data-testid="main-title" className="text-3xl font-bold">
          {`Welcome, ${user.username}!`}
        </h1>
        <button
          data-testid="logout-btn"
          onClick={() => logout()}
          className="rounded-md bg-neutral-200 px-4 py-2 font-semibold hover:bg-neutral-300"
        >
          Logout
        </button>
      </div>

      <section className="card flex flex-col gap-4 p-4">
        <h2 className="text-xl font-semibold">Create a channel</h2>
        <form onSubmit={handleCreateChannel} className="flex gap-2">
          <input
            id="channel-name-input"
            data-testid="channel-name-input"
            value={channelName}
            onChange={(e) => setChannelName(e.target.value)}
            placeholder="e.g. #announcements"
            className="flex-1 rounded-md border border-neutral-300 px-3 py-2"
          />
          <button
            id="create-channel-btn"
            data-testid="create-channel-btn"
            type="submit"
            className="rounded-md bg-primary-500 px-4 py-2 font-semibold"
          >
            Create Channel
          </button>
        </form>
        {error && <span className="text-sm text-red-500">{error}</span>}
      </section>

      <section className="card flex flex-col gap-2 p-4">
        <h2 className="text-xl font-semibold">Channels</h2>
        <div data-testid="channels-list" className="flex flex-col gap-2">
          {(channels ?? []).map((channel) => (
            <Link
              key={channel.id}
              data-testid="channel-link"
              data-channel-id={channel.id}
              to={`/channel/${channel.id}`}
              className="rounded-md border border-neutral-200 px-4 py-2 font-medium hover:bg-neutral-100"
            >
              {channel.name}
            </Link>
          ))}
        </div>
      </section>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Link, useParams } from "react-router";
import {
  createMessage,
  getChannel,
  getChannelMessages,
  markAsRead,
  useQuery,
} from "wasp/client/operations";
import { useSocket, useSocketListener } from "wasp/client/webSocket";

const TYPING_TIMEOUT_MS = 3000;

export function ChannelPage() {
  const { id } = useParams<"id">();
  const channelId = Number(id);

  const { data: channel } = useQuery(getChannel, { channelId });
  const { data: messages, refetch: refetchMessages } = useQuery(
    getChannelMessages,
    { channelId },
  );

  const { socket } = useSocket();

  const [activeUsers, setActiveUsers] = useState<string[]>([]);
  const [typingUsers, setTypingUsers] = useState<Record<string, boolean>>({});
  const [messageText, setMessageText] = useState("");

  const isTypingRef = useRef(false);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout>>();

  // Join/leave the channel's WebSocket room as we navigate in/out of it.
  useEffect(() => {
    if (!channelId) {
      return;
    }
    socket.emit("joinChannel", { channelId });
    return () => {
      socket.emit("leaveChannel", { channelId });
    };
  }, [socket, channelId]);

  useSocketListener("activeUsers", (usernames) => {
    setActiveUsers(usernames);
  });

  useSocketListener("typing", ({ username, isTyping }) => {
    setTypingUsers((prev) => {
      const next = { ...prev };
      if (isTyping) {
        next[username] = true;
      } else {
        delete next[username];
      }
      return next;
    });
  });

  useSocketListener("messageCreated", () => {
    void refetchMessages();
  });

  useSocketListener("readReceiptUpdated", () => {
    void refetchMessages();
  });

  // Mark the latest message as read whenever the message list changes so
  // read receipts stay up to date in (near) real time.
  const lastMarkedMessageIdRef = useRef<number | null>(null);
  useEffect(() => {
    if (!messages || messages.length === 0) {
      return;
    }
    const lastMessage = messages[messages.length - 1];
    if (lastMarkedMessageIdRef.current === lastMessage.id) {
      return;
    }
    lastMarkedMessageIdRef.current = lastMessage.id;
    markAsRead({ channelId, lastReadMessageId: lastMessage.id }).catch(() => {
      // Ignore - a failed read receipt update isn't critical.
    });
  }, [messages, channelId]);

  function stopTyping() {
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = undefined;
    }
    if (isTypingRef.current) {
      isTypingRef.current = false;
      socket.emit("typing", { channelId, isTyping: false });
    }
  }

  // Any keystroke in the message input (debounced) marks us as typing, and
  // resets a 3-second local timer that clears the typing state once we stop.
  function handleKeyDown() {
    if (!isTypingRef.current) {
      isTypingRef.current = true;
      socket.emit("typing", { channelId, isTyping: true });
    }
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }
    typingTimeoutRef.current = setTimeout(() => {
      isTypingRef.current = false;
      socket.emit("typing", { channelId, isTyping: false });
    }, TYPING_TIMEOUT_MS);
  }

  // Clear the typing state when leaving the page.
  useEffect(() => {
    return () => {
      stopTyping();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function handleSend(e: React.FormEvent) {
    e.preventDefault();
    const content = messageText.trim();
    if (!content) {
      return;
    }
    stopTyping();
    setMessageText("");
    await createMessage({ channelId, content });
  }

  const typingUsernames = Object.keys(typingUsers);

  return (
    <div className="mx-auto flex max-w-3xl flex-col gap-6 p-8">
      <Link
        data-testid="back-to-channels"
        to="/"
        className="text-sm font-semibold underline"
      >
        &larr; Back to channels
      </Link>

      <h1 data-testid="channel-title" className="text-3xl font-bold">
        {channel?.name ?? ""}
      </h1>

      <section>
        <h2 className="mb-2 text-sm font-semibold uppercase text-neutral-500">
          Active users
        </h2>
        <div data-testid="active-users-list" className="flex flex-wrap gap-2">
          {activeUsers.map((username) => (
            <span
              key={username}
              data-testid="active-user-item"
              data-username={username}
              className="rounded-full bg-green-100 px-3 py-1 text-sm"
            >
              {username}
            </span>
          ))}
        </div>
      </section>

      <div
        data-testid="typing-indicators"
        className="min-h-6 text-sm italic text-neutral-500"
      >
        {typingUsernames.map((username) => (
          <span
            key={username}
            data-testid="typing-user-item"
            data-username={username}
          >
            {username} is typing...
          </span>
        ))}
      </div>

      <section className="flex flex-col gap-3">
        <div data-testid="messages-list" className="flex flex-col gap-3">
          {(messages ?? []).map((message) => (
            <div
              key={message.id}
              data-testid="message-item"
              data-message-id={message.id}
              className="rounded-md border border-neutral-200 p-3"
            >
              <div className="flex items-baseline gap-2">
                <span data-testid="message-sender" className="font-semibold">
                  {message.sender.username}
                </span>
                <span data-testid="message-content">{message.content}</span>
              </div>
              <div
                data-testid="message-read-receipts"
                className="mt-1 flex gap-2 text-xs text-neutral-500"
              >
                {message.readers.map((reader) => (
                  <span
                    key={reader.userId}
                    data-testid="reader-name"
                    data-username={reader.username}
                  >
                    {reader.username}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>

        <form onSubmit={handleSend} className="flex gap-2">
          <input
            id="message-input"
            data-testid="message-input"
            value={messageText}
            onChange={(e) => setMessageText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type a message..."
            className="flex-1 rounded-md border border-neutral-300 px-3 py-2"
          />
          <button
            id="send-message-btn"
            data-testid="send-message-btn"
            type="submit"
            className="rounded-md bg-primary-500 px-4 py-2 font-semibold"
          >
            Send
          </button>
        </form>
      </section>
    </div>
  );
}

